const input = $input.all()[0].json;

// If Urdu shortcut was taken
if (input.skipOllama) {
  if (input.studentName === 'unknown') {
    return [{ json: {
      studentName:     'unknown',
      queryType:       'unknown',
      originalMessage: input.originalMessage,
      error:           true,
      reply:           'براہ کرم طالب علم کا نام بتائیں۔ مثال: علی کی حاضری کیا ہے؟'
    }}];
  }
  return [{ json: {
    studentName:     input.studentName,
    queryType:       input.queryType,
    originalMessage: input.originalMessage,
    error:           false
  }}];
}

// English path — parse Ollama response
const raw = input.response || '';
// ... rest of existing parse code

const input       = $input.all()[0].json.body;
const question    = input.content;
const studentName = input.authorName || 'Parent';
const isUrdu      = /[\u0600-\u06FF]/.test(question);

// Urdu keyword fallback — don't rely on Ollama for Urdu
if (isUrdu) {
  const urduToEnglish = {
    'علی':'Ali','زید':'Zaid','سارہ':'Sara','احمد':'Ahmed',
    'عمر':'Omar','فاطمہ':'Fatima','حسن':'Hassan','بلال':'Bilal',
    'حمزہ':'Hamza','انس':'Anas','زینب':'Zainab','نور':'Noor'
  };

  let extractedName = 'unknown';
  const nameMatch = question.match(/([ا-ی]{2,})\s+(کی|کا|کو|نے)/);
  if (nameMatch) {
    const urduName = nameMatch[1];
    extractedName = urduToEnglish[urduName] || urduName;
  }

  let queryType = 'general';
  if (/حاضری|حاضر/.test(question))         queryType = 'attendance';
  if (/فیس|ادائیگی|رقم/.test(question))     queryType = 'fees';
  if (/ہوم ورک|ہوم‌ورک/.test(question))    queryType = 'homework';

  return [{
    json: {
      originalMessage: question,
      skipOllama:      true,
      studentName:     extractedName,
      queryType:       queryType
    }
  }];
}

// English — use Ollama
const prompt = `A parent sent this message. Extract student name and query type. Return ONLY JSON.

Message: "${question}"

Return:
{"studentName":"first name only","queryType":"general or fees or attendance or homework"}

If no student name found use "unknown". JSON only:`;

return [{
  json: {
    originalMessage: question,
    skipOllama:      false,
    ollamaBody: JSON.stringify({
      model:  'llama3.2:1b',
      prompt: prompt,
      stream: false
    })
  }
}];

const query      = $('Parse Parent Query').first().json;
const studentName = query.studentName;
const queryType   = query.queryType;

const studentRows    = $('Get Student Data').all();
const feeRows        = $('Get Fee Data').all();
const attendanceRows = $('Get Attendance Data').all();
const homeworkRows   = $input.all();

// Student not found
if (!studentRows.length || !studentRows[0].json.StudentID) {
  return [{ json: { 
    reply: `I couldn't find a student named ${studentName} in the system. Please check the name and try again.`
  }}];
}

const student = studentRows[0].json;

// Calculate attendance
let attendanceInfo = 'No attendance records yet.';
if (attendanceRows.length && attendanceRows[0].json.StudentName) {
  const total   = attendanceRows.length;
  const present = attendanceRows.filter(r => (r.json.Status || '').toLowerCase() === 'present').length;
  const absent  = attendanceRows.filter(r => (r.json.Status || '').toLowerCase() === 'absent').length;
  const late    = attendanceRows.filter(r => (r.json.Status || '').toLowerCase() === 'late').length;
  const pct     = Math.round(((present + late * 0.5) / total) * 100);
  const emoji   = pct >= 75 ? '✅' : pct >= 60 ? '⚠️' : '🔴';
  attendanceInfo = `${emoji} ${pct}% (${present} present, ${absent} absent, ${late} late out of ${total} days)`;
}

// Fee info
let feeInfo = 'No fee records found.';
if (feeRows.length && feeRows[0].json.StudentName) {
  const latestFee = feeRows[feeRows.length - 1].json;
  const paid      = latestFee.Status === 'Paid';
  const partial   = latestFee.Status === 'Partial';
  const emoji     = paid ? '✅' : partial ? '⚠️' : '🔴';
  feeInfo = paid
    ? `${emoji} Paid — PKR ${latestFee.AmountDue} for ${latestFee.Month}`
    : partial
    ? `${emoji} Partial — PKR ${latestFee.AmountPaid} paid of PKR ${latestFee.AmountDue} for ${latestFee.Month}. Remaining: PKR ${parseFloat(latestFee.AmountDue) - parseFloat(latestFee.AmountPaid)}`
    : `${emoji} Pending — PKR ${latestFee.AmountDue} for ${latestFee.Month}. Due: ${latestFee.DueDate}`;
}

// Homework info
let homeworkInfo = 'No homework assigned.';
if (homeworkRows.length && homeworkRows[0].json.StudentName) {
  const pending = homeworkRows.filter(r => (r.json.Status || '').toLowerCase() !== 'submitted');
  const done    = homeworkRows.filter(r => (r.json.Status || '').toLowerCase() === 'submitted');
  if (pending.length) {
    const list = pending.map(r => `   • ${r.json.Subject}: ${r.json.Description} (Due: ${(r.json.DueDate || '').split('T')[0]})`).join('\n');
    homeworkInfo = `${pending.length} pending:\n${list}`;
    if (done.length) homeworkInfo += `\n   ✅ ${done.length} submitted`;
  } else {
    homeworkInfo = `✅ All ${done.length} assignment(s) submitted`;
  }
}

// Build response based on queryType
let reply = '';

if (queryType === 'fees') {
  reply = `Fee status for ${student.Name}:\n\n💰 ${feeInfo}`;

} else if (queryType === 'attendance') {
  reply = `Attendance for ${student.Name}:\n\n📊 ${attendanceInfo}`;

} else if (queryType === 'homework') {
  reply = `Homework for ${student.Name}:\n\n📚 ${homeworkInfo}`;

} else {
  reply = `Summary for ${student.Name} (Grade ${student.Grade}):\n\n📊 Attendance: ${attendanceInfo}\n\n💰 Fees: ${feeInfo}\n\n📚 Homework: ${homeworkInfo}`;
}

return [{ json: { reply } }];
